 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the solid separator; the patterned encoding is on its right or below.
    row_sep = next((r for r, row in enumerate(grid) if len(set(row)) == 1), None)
    col_sep = next((c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1), None)
    if col_sep is not None and (row_sep is None or h - row_sep - 1 < w - col_sep - 1):
        panel = [row[col_sep + 1:] for row in grid]
        colors = {v for row in panel for v in row}
    elif row_sep is not None:
        panel = grid[row_sep + 1:]
        colors = {v for row in panel for v in row}
    else:
        raise ValueError('no solid divider')
    # Demos encode sparse marked cells among a uniform background. Marks become 3.
    counts = {v: sum(x == v for row in panel for x in row) for v in colors}
    mark = min(colors, key=counts.get)
    return [[3 if v == mark else 4 for v in row] for row in panel]

if __name__ == '__main__':
